import { buildSectionPage } from '../../../utils/section-page.utils.js';
import '../project-dashboard/project-git-log/project-git-log.component.js';
import type { ProjectGitLog } from '../project-dashboard/project-git-log/project-git-log.component.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';

export class ProjectsGitLogScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;

        const page = buildSectionPage(this, 'Git Activity', 'projects', '/projects');
        const intro = document.createElement('p');
        intro.textContent = 'Recent commits stay collapsed by default. Expand a row to see author and full hash details.';
        page.content.append(intro, this.statusNodes.errorNode);

        const gitLog = document.createElement('project-git-log') as ProjectGitLog;
        gitLog.setAttribute('project-id', 'motivation');
        page.content.appendChild(gitLog);
    }
}

if (!customElements.get('projects-git-log-screen')) {
    customElements.define('projects-git-log-screen', ProjectsGitLogScreen);
}
